describe('View Item Details', () => {
    beforeEach(() => {
        cy.visit('/items'); // Adjust the URL to your application's item listing page
    });

    it('should display item details when an item is clicked', () => {
        cy.get('.item').first().click(); // Assuming items have a class of 'item'
        cy.url().should('include', '/items/'); // Check if the URL changes to the item details page
        cy.get('.item-details').should('be.visible'); // Assuming item details have a class of 'item-details'
        cy.get('.item-title').should('exist'); // Check if the item title is displayed
        cy.get('.item-description').should('exist'); // Check if the item description is displayed
    });

    it('should show a 404 error when an invalid item is accessed', () => {
        cy.visit('/items/invalid-id'); // Replace 'invalid-id' with a non-existent item ID
        cy.get('.error-message').should('be.visible'); // Assuming there's an error message for invalid items
        cy.get('.error-message').should('contain', 'Item not found'); // Check for specific error message
    });
});
